mapper.select:
SELECT distinct STL_SEC_ACCT_INFO.SEC_ACCT_ID secAcctId, STL_SEC_ACCT_INFO.SEC_ACCT_NAME secAcctName, STL_SEC_ACCT_INFO.manager manager, MST_CUSTOMER_INFO.CUSTOMER_NAME managerName, /*基金管理人*/ STL_SEC_ACCT_INFO.REMARK remark FROM STL_SEC_ACCT_INFO LEFT JOIN MST_CUSTOMER_INFO ON STL_SEC_ACCT_INFO.manager = MST_CUSTOMER_INFO.customer_id WHERE 1=1 AND STL_SEC_ACCT_INFO.sec_acct_type = 'FUND'/*只查询基金账户*/
AND (STL_SEC_ACCT_INFO.SEC_ACCT_ID LIKE concat('%',concat(#{secAcctId},'%')) OR STL_SEC_ACCT_INFO.SEC_ACCT_NAME LIKE concat('%',concat(#{secAcctId},'%')))
AND STL_SEC_ACCT_INFO.manager = #{manager}

		select count(*) 
        	from STL_SEC_ACCT_INFO
        WHERE 
        	SEC_ACCT_ID=#{secAcctId,jdbcType=VARCHAR}
        	/*只查询基金账户*/

select T2.SEC_ACCT_ID secAcctId, T2.SEC_ACCT_NAME secAcctName, T2.SEC_ACCT_SOURCE secAcctSource, T2.REGIST_ORG registOrg, T2.TRD_ACCT_ID trdAcctId, T2.REC_ACCT_ID recAcctId, T2.REMARK remark, T2.CREATE_USER createUser, T2.CREATE_DEPT createDept,T2.CREATE_TIME createTime, T2.UPDATE_USER updateUser, T2.UPDATE_TIME updateTime from PTL_SEC_ACCT T1 ,STL_SEC_ACCT_INFO T2 where T1.ACCT_NO=T2.SEC_ACCT_ID AND T2.SEC_ACCT_ID in
#{item.secAcctId,jdbcType=VARCHAR}
AND T2.sec_acct_type = 'FUND'/*只查询基金账户*/
